"""Run the authors' actual metric functions on source-faithful row multiplicity.
Keep the deduplicated panel as a separate sensitivity analysis, never silently change it.
"""
import pathlib,json,ast,hashlib
import pandas as pd,numpy as np
from scipy import stats
ROOT=pathlib.Path('/home/boltzmann13/IMRAN/NOV26/cirspr-sci-env/05_validated_benchmarks/CURRENT.txt').read_text();ROOT=pathlib.Path(ROOT)
x=pd.read_csv(ROOT/'predictions/cas9_exact_notebook_multiplicity_replay.csv');audit=json.loads((ROOT/'reports/cas9_source_multiplicity_audit.json').read_text());assert audit['source_no_dedup_join_matches_cached_counts']
cols={'RS3_Sequence_fresh':'Rule Set 3 (sequence)','CRISPRon':'CRISPRon','DeepSpCas9_author_archive':'DeepSpCas9','Rule Set 2_author_archive':'Rule Set 2'}
y=x.rename(columns=cols);long=y.melt(id_vars=['sgRNA Sequence','sgRNA Context Sequence','PAM Sequence','sgRNA Activity','sgRNA Target','dataset','genomewide'],value_vars=list(cols.values()),var_name='model',value_name='prediction')
source=ROOT/'sources/rs_dev/code/core.py';tree=ast.parse(source.read_text());wanted=['calculate_prediction_cors','get_model_correlations','calculate_model_rank_loss','get_model_rank_loss'];nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in wanted];assert len(nodes)==4
namespace={'pd':pd,'np':np,'stats':stats,'tqdm':lambda v:v};code=compile(ast.Module(body=nodes,type_ignores=[]),str(source),'exec');exec(code,namespace)
protocol={'source_metric_functions':wanted,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'source_commit':'e92c3a8dc1d2452ffd979c094ec7d9e1f9b754e9','observations':len(x),'unique_contexts':x['sgRNA Context Sequence'].nunique(),'counts_match_cached_author_execution':True,'data_multiplicity':'Original many-to-many merge behavior recreated from author CRISPRon table multiplicities. Duplicate observation weighting is retained solely for source-faithful replay; deduplicated inference/metrics remain separately available.','fresh_models':['Rule Set 3 (sequence)','CRISPRon'],'author_score_replays':['DeepSpCas9','Rule Set 2'],'metrics':'Unmodified source calculate/get correlation functions, 1000 row bootstraps. Genomewide rank loss uses source80% gene subsampling without replacement, not a classical full-gene bootstrap.','analysis_reconciliation':'Cohort multiplicity corrected from source code independently of score performance; no model or threshold tuning. Prior deduplicated results retained.'}
(ROOT/'protocols/cas9_exact_source_replay.json').write_text(json.dumps(protocol,indent=2));print('SOURCE_REPLAY_START',len(x),flush=True)
metrics=namespace['get_model_correlations'](long,nboots=1000);metrics['inference_mode']=metrics.model.astype(str).map({'Rule Set 3 (sequence)':'FRESH_INFERENCE','CRISPRon':'FRESH_INFERENCE','DeepSpCas9':'AUTHOR_SCORE_REPLAY','Rule Set 2':'AUTHOR_SCORE_REPLAY'});metrics.to_csv(ROOT/'reports/cas9_exact_published_protocol_metrics.csv',index=False)
print(metrics[['dataset','model','size','spearman','spearman_025','spearman_975','inference_mode']].to_string(index=False),flush=True)
rank=namespace['get_model_rank_loss'](long[long.genomewide].copy(),nboots=1000);rank.to_csv(ROOT/'reports/cas9_exact_source_within_gene_rank_loss.csv',index=False)
(ROOT/'reports/cas9_source_replay_status.json').write_text(json.dumps({'status':'COMPLETED_SOURCE_FAITHFUL_RS3_COMPARISON_PROTOCOL','unique_contexts':23629,'observations':len(x),'dataset_counts':x.groupby('dataset').size().to_dict(),'training_sequence_exclusion':'verified exact20mer union of four source model training lists','caveats':['Duplicate-key observation weighting retained for reproduction, not endorsed as independent biological evidence','RS3 Sequence+Target not substituted; target-feature model not part of this evaluation','Original CRISPRon_v0 internal0.80 and separate <=3mm exclusion protocol not claimed reproduced','Two baselines are author-score metric replays, not fresh local inference']},indent=2))
print('SOURCE_REPLAY_COMPLETE',flush=True)
